"""Honest scorecard: unavailable judge metrics never become zero or a passing score."""
from collections import Counter
import statistics,json

def avg(values):
 values=[v for v in values if v is not None];return sum(values)/len(values) if values else None
def pct(v):return 'N/A' if v is None else f'{100*v:.1f}%'
def table(headers,rows):return '\n'.join(['| '+' | '.join(headers)+' |','|'+'|'.join(['---']*len(headers))+'|']+['| '+' | '.join(map(str,row))+' |' for row in rows])
def write_report(p,E):
 rs=p['questions'];answerable=[r for r in rs if not r['unanswerable']];neg=[r for r in rs if r['unanswerable']];par=p['parsing']
 terms=avg([r['reference_term_coverage'] for r in answerable]);rec=avg([r['metrics']['5']['recall'] for r in answerable]);abst=avg([r['correct_negative'] for r in neg]);sim=avg([r['ragas']['answer_similarity'] for r in rs]);cit=avg([r['citation_source_accuracy'] for r in rs])
 # Operational diagnostic index, explicitly not overall semantic quality; missing judge scores excluded visibly.
 components=[avg([avg([v['text_completeness'] for v in m['pages']]) for m in par]),rec,terms,abst]
 diagnostic=avg(components)
 scores=[['Parsing: text token completeness',pct(components[0]),'20 pages; visual semantics excluded'],['Parsing: page assignment',pct(avg([m['page_mapping_accuracy'] for m in par])),'Chunk text matches independent source-page transcript'],['OCR WER',pct(avg([v['wer'] for m in par for v in m['pages']])),'Lower is better; authored scan transcription'],['Table cell text availability',pct(avg([t['cell_content_accuracy'] for m in par for t in m['tables']])),'Flat cell token presence, not structure'],['Table structure preservation','0.0%','No structured table output'],['Figure detection recall','0.0%','No figure detector; page previews are not detections'],['Retrieval recall@5',pct(rec),'Answerable questions only'],['Generation: reference-term coverage',pct(terms),'Deterministic diagnostic; NOT RAGAS correctness'],['RAGAS answer similarity',pct(sim),'Actual RAGAS with app BGE embeddings'],['RAGAS judge metrics','N/A' if not any(r['ragas'].get('faithfulness') is not None for r in rs) else pct(avg([r['ragas'].get('faithfulness') for r in rs])),'Free-tier credentials missing for present run'],['Citation page/chunk accuracy',pct(cit),'Conditional on emitted citations'],['Correct negative abstention',pct(abst),f'{len(neg)} negative questions'],['App clickable citations','N/A','Isolated core evaluation does not create authenticated source URLs'],['Trust numeric correlation','N/A','App exposes confidence labels, not requested numerical scores'],['Robustness','Measured' if p['robustness'] else 'Not in selected slice','Four variants; two questions each'],['System','Measured','Local stage latency/usage; excludes HTTP upload/queue/DB']]
 sections=['# HomeAtlas multimodal RAG evaluation',
 f'**Status: partial evaluation, {len(rs)}/60 questions executed. Overall semantic-quality score: unavailable.** Seven required RAGAS judge metrics and free-tier visual judging could not run because no credential is configured. Missing scores are null, never imputed as passing or zero. No application logic or household data was changed.',
 f'**Observed operational diagnostic index: {pct(diagnostic)}**, equal mean of four disclosed measurements: extraction token completeness, final recall@5, reference-term coverage and negative abstention. This is 4/4 diagnostic inputs, **not** a comprehensive quality score or replacement for RAGAS. Required judge metric coverage: {sum(r["ragas"].get(k) is not None for r in rs for k in ["faithfulness","answer_relevancy","context_precision","context_recall","answer_correctness","multimodal_faithfulness","multimodal_relevance"])}/{len(rs)*7} question-metric observations; answer-similarity coverage: {sum(r["ragas"].get("answer_similarity") is not None for r in rs)}/{len(rs)}.',
 '## Summary scorecard',table(['Component','Score/status','Interpretation'],scores),
 '## Setup, scope and reproducibility',
 'Five original CC0 PDFs, four pages each, 60 independently authored questions: 12 per modality, 50 answerable and 10 unanswerable. Question types include factual, multi-chunk, cross-modal, summary, numeric/chart-reading and absent-evidence cases. Ground truth is authored from fixture specifications and the rendered scan sample was visually reviewed. Each question has source pages and mapped exact app chunk IDs. This small, clean synthetic corpus is a diagnostic benchmark, not a representative customer-data estimate.',
 'The evaluator imports the **actual** app `extract`, `rank_candidates`, `answer_from_evidence`, and `LocalModels` implementations. It mirrors ingestion embedding attachment and uses an isolated in-memory corpus. It does not invoke the HTTP upload, queue, database authorization/credit transactions or browser citation viewer. Those are out of this measured scope; prior app audits are not counted here. All writes, fixtures, dependency additions and caches reside under evaluation.',
 table(['Model','Identity'],[[k,v] for k,v in p['models'].items()]),
 'Python 3.12; PyMuPDF, Tesseract OCR, NumPy, Torch/Transformers and RAGAS 0.2.15. Seed 741, local generation temperature 0; app does not set an Ollama inference seed, so cold generative repeats are not guaranteed bitwise identical. Completed model outputs are cached. Model revisions match the app. requirements.lock.txt pins the installed environment; app dependencies are read-only. Free judge supports OpenRouter free IDs only; actual returned provider/model and usage are saved in cache when configured.',
 '## Modality comparison',table(['Modality','N','Recall@5','Term coverage','RAGAS similarity','Abstention on negatives'],[[m,str(len([r for r in rs if r['modality']==m])),pct(avg([r['metrics']['5']['recall'] for r in answerable if r['modality']==m])),pct(avg([r['reference_term_coverage'] for r in answerable if r['modality']==m])),pct(avg([r['ragas']['answer_similarity'] for r in rs if r['modality']==m])),pct(avg([r['correct_negative'] for r in neg if r['modality']==m]))] for m in ['text','table','image','chart','scanned']]),
 'Image/chart semantic understanding is the measured weak point: PDF pages with native headers enter the native-text branch; text inside embedded raster figures is not OCRed. Page previews receive image embeddings but no figure captions or structured chart values are created. The ordinary text-query generator receives retrieved text, **not the source page images**. Thus retrieving the right page is insufficient to answer visual questions. No external judge interpretation is counted as an app capability.',
 '## 1. Parsing and OCR',table(['Modality','Text completeness','Page assignment','CER','WER','Chunks','Ingestion s/page'],[[m['modality'],pct(avg([x['text_completeness'] for x in m['pages']])),pct(m['page_mapping_accuracy']),pct(avg([x['cer'] for x in m['pages']])),pct(avg([x['wer'] for x in m['pages']])),m['chunk_count'],f"{m['ingestion_seconds_per_page']:.3f}"] for m in par]),
 'Text completeness measures authored native text (or OCR transcription) token recall; it deliberately excludes diagram/chart raster text and cannot establish semantic completeness. Page assignment requires normalized chunk text to occur in the independently authored matching source-page transcript; identical repeated lines can be ambiguous. Citation correctness additionally matches independently annotated question source pages. OCR sample is the four authored image-only pages with saved reference/extracted text in results.json.',
 table(['Table page','Cell text availability','Structured cell accuracy','Rows/columns preserved'],[[t['page'],pct(t['cell_content_accuracy']),pct(t['structured_cells_accuracy']),pct(t['row_column_structure_preservation'])] for m in par for t in m['tables']]),
 'Cell text availability checks exact cell strings in flattened page output, not whether the system relates each value to its correct header. Structured cell accuracy is zero because the app emits no table cell coordinates or row/column object. Eight expected figures (four diagrams/four charts), zero dedicated detections; rendered whole-page previews have 100% page coverage but do not count as figure detection.',
 '## 2. Image and chart understanding',
 'Caption correctness/completeness/invented-details rubric: **unsupported app stage**, because no image caption/description output exists to score. Free-tier visual judging of generated visual answers: **blocked by missing credential**. Chart value/trend/axis/legend questions are included in per-question results and reference-term diagnostics. Semantic chart-reading accuracy and image-description hallucination rates remain unavailable without a judge and/or an app description output; safe abstention is reported separately.',
 table(['Chart question','Term coverage','Mode'],[[r['id'],pct(r['reference_term_coverage']),r['result']['mode']] for r in rs if r['modality']=='chart' and not r['unanswerable']]),
 '## 3. Chunking',table(['Modality','Min chars','Median chars','Max chars','Chunks'],[[m['modality'],min(m['chunk_sizes']),statistics.median(m['chunk_sizes']),max(m['chunk_sizes']),len(m['chunk_sizes'])] for m in par]),
 'The app groups native blocks up to 1200 characters within a page and emits OCR lines separately. It never merges evidence across pages. Multi-page questions therefore require multiple chunks; the generator permits at most two short quotes, which limits four-page summaries. Tables remain within one page chunk here but flatten header/cell relationships. Figure+caption semantic pairs are absent, not merely split. These short fixtures do not stress the 1200-character boundary; this is a coverage limitation.',
 '## 4–6. Retrieval and reranking',
 'Gold relevance is the set of exact chunks on independently annotated relevant pages, including page preview carriers. This is **page-grounded relevance**, not a claim every chunk contains the answer. Scans have several relevant page chunks, so chunk recall is strict; evidence-term availability is independently reported. Unanswerable questions are excluded from ranking averages. The app returns at most five final chunks; @10 uses denominator 10 and does not fabricate extra results. Before-rerank comparison uses the same five-result budget; full 16 candidate IDs are retained in raw JSON.']
 for group in ['overall','text','table','image','chart','scanned']:
  subset=answerable if group=='overall' else [r for r in answerable if r['modality']==group]
  rows=[]
  for k in [1,3,5,10]:
   rows.append([k]+[pct(avg([r['metrics'][str(k)][metric] for r in subset])) for metric in ['precision','recall','hit','mrr','ndcg','ap']])
  sections += [f'### {group}',table(['K','Precision','Recall','Hit rate','MRR','NDCG','MAP@K'],rows)]
 sections += [table(['Ranking (K=5)','Precision','Recall','Hit','MRR','NDCG','MAP@5'],[[label]+[pct(avg([r[field]['5'][metric] for r in answerable])) for metric in ['precision','recall','hit','mrr','ndcg','ap']] for label,field in [('Before rerank (fusion top five)','before_metrics'),('After rerank and production filter','metrics')]]),
 table(['Final set','Precision','Recall','MAP'],[['Overall',pct(avg([r['final_metrics']['precision'] for r in answerable])),pct(avg([r['final_metrics']['recall'] for r in answerable])),pct(avg([r['final_metrics']['ap'] for r in answerable]))]]),
 'Cross-modal text queries: source modality hit@5 '+pct(avg([r['source_modality_hit'] for r in answerable]))+'. Per-question top-K modality mixtures are recorded in JSON using both ground-truth source modality and the app-emitted modality. Native table/image/chart pages are labeled text by the app; this distinction is retained.',
 table(['Image query source','Correct source page hit@5','Correct text chunk hit@5','Returned app modalities'],[[r['modality'],pct(r['source_page_hit_at_5']),pct(r['image_query_to_text_hit_at_5']),json.dumps(r['app_modality_mix'])] for r in p['image_queries']]),
 '## 7. RAGAS generation evaluation',table(['Metric','Mean','Scored questions'],[[k,pct(avg([r['ragas'].get(k) for r in rs])),sum(r['ragas'].get(k) is not None for r in rs)] for k in ['faithfulness','answer_relevancy','context_precision','context_recall','answer_correctness','answer_similarity','multimodal_faithfulness','multimodal_relevance']]),
 'All eight metrics use RAGAS implementations; answer similarity runs locally with the app’s BGE model. Seven judge-dependent metrics are null without OPENROUTER_API_KEY. The evaluator uses actual RAGAS MultiModalFaithfulness/MultiModalRelevance with retrieved text and local page image paths; the judge can inspect retrieved images, but this does not mean the app generator saw them. Retry/backoff, bounded HTTP errors, raw response cache and per-metric cache support resuming. The judge integration is import-checked but live external calls are unverified because credentials are absent.',
 '## 8. Citations and visual grounding',
 f'Conditional citation source/page/chunk accuracy: {pct(cit)}. Answerable questions with at least one correct emitted citation: {pct(avg([r["has_valid_citation"] for r in answerable]))}. Visual bbox/page-region match: {pct(avg([r["citation_visual_region_match"] for r in rs]))}. These are local metadata/exact quote checks. The app’s authenticated clickable citation URL/browser navigation is **not tested** by this isolated corpus; no synthetic link is substituted for a real app URL.',
 '## 9. Trust metrics',
 'The app returns categorical confidence (`supported`, `insufficient`, `conflicting`) and optional owner diagnostics, not numeric relevance/correctness/authenticity trust scores. Therefore requested numerical correlation/calibration is unsupported. Relevance is an internal reranker score rather than answer correctness. Confidence labels are retained for each question; negative abstention agreement is measured below, but is not a proxy for three missing scores.',
 '## 10. Negative cases',
 f'Correct abstention: {pct(abst)} ({sum(r["correct_negative"]==1 for r in neg)}/{len(neg)}). Non-abstention on absent evidence: {pct(avg([r["negative_nonabstention"] for r in neg]))}. Questions include an undocumented purple valve; any answer on those is flagged in raw results. Non-abstention is a diagnostic failure, not automatically a hallucinated fact. Semantic hallucination rate remains judge-blocked. Exact-copy citation validation prevents invented quoted text but does not prove relevance or correctness.',
 '## 11. Robustness',table(['Variant','CER','WER','Mean term coverage','Drop vs original'],[[r['variant'],pct(r['cer']),pct(r['wer']),pct(avg([q['term_coverage'] for q in r['questions']])),pct(avg([q['score_drop'] for q in r['questions']]))] for r in p['robustness']]),
 'Each variant replaces scan page 1 in the full corpus and reruns the same two pressure/date questions: 300×375 low-resolution resampling, 90-degree rotation, Gaussian blur plus seeded noise, and mixed English/Spanish/French text. Drop is baseline reference-term coverage minus degraded coverage; negative drop means improvement. Mixed-language text is an added-language robustness check with the same English target facts, not a multilingual semantic benchmark. Changed pages use the same app text and image embeddings as baseline ingestion.',
 '## 12. System metrics']
 latency=[]
 for mod in ['overall','text','table','image','chart','scanned']:
  subset=rs if mod=='overall' else [r for r in rs if r['modality']==mod]
  for stage in ['retrieval','generation','total']:
   vals=sorted(r['timings'][stage] for r in subset)
   latency.append([mod,stage,f'{avg(vals):.3f}' if vals else 'N/A',f'{vals[max(0,mathceil(.95*len(vals))-1)]:.3f}' if vals else 'N/A'])
 sections += [table(['Modality','Stage','Mean seconds','p95 seconds'],latency)]
 stages=[]
 for stage in ['text_embedding','image_embedding','reranking','generation']:
  vals=[c['seconds'] for r in rs for c in r['stage_calls'] if c['stage']==stage]
  stages.append([stage,f'{avg(vals):.3f}' if vals else 'N/A',f'{sorted(vals)[mathceil(.95*len(vals))-1]:.3f}' if vals else 'N/A',len(vals)])
 usage=[u for r in rs for u in r['token_usage']]
 sections += [table(['Instrumented call','Mean s','p95 s','Calls'],stages),f'Observed local generation usage: {sum(u.get("prompt_eval_count") or 0 for u in usage)} prompt tokens and {sum(u.get("eval_count") or 0 for u in usage)} generated tokens across {len(usage)} HTTP responses. These are observed Ollama counters, not estimates. Cached generation calls retain their original response result but may have no newly observed token response; raw question results preserve the initial usage. Judge usage is unavailable without credentials. End-to-end core timings include local extraction/retrieval/generation only, not network upload, queue wait, DB writes or UI rendering. Cached question rows retain original timings; per-call cache flags are in JSON.',
 '## Top failures and per-question results',table(['ID','Modality/type','Term coverage','Reason'],[[r['id'],r['modality']+'/'+r['type'],pct(r['reference_term_coverage']),'Abstained despite answerable source' if r['abstention'] else 'Reference terms missing; inspect raw quote/context'] for r in sorted(answerable,key=lambda r:r['reference_term_coverage'] or 0)[:20]]),
 'All 60 raw question outputs, references, exact chunk IDs, top-K metrics, modalities, timings, RAGAS statuses and citations are in results.json; results.csv is a compact analysis table. testset.json preserves authored source page/region annotations and exact mapped chunk IDs.',
 '### Concrete failure examples',
 '\n'.join(f'- **{r["id"]}**: {r["question"]} Reference: {r["reference_answer"]} Observed: {r["result"]["answer"].replace(chr(10), " " )}' for r in rs if r['id'] in ['image-07','chart-01','text-10','table-09','scanned-10']),
 '## Prioritized recommendations',
 '1. **P0 — visual evidence delivery:** extract embedded raster figures even on native-text pages, OCR their labels, retain figure regions/captions and pass retrieved source images into the vision generator. Keep exact citation validation and safe abstention.\n2. **P0 — tables:** add structured row/column extraction with header associations and retain both structured text and source-region coordinates.\n3. **P1 — multi-page answers:** evaluate expanding the two-quote cap and preserving facts across more than two retrieved chunks; use targeted summaries with clear citations.\n4. **P1 — OCR robustness:** orientation correction, image preprocessing, multilingual OCR configuration, and page-level grouping.\n5. **P1 — evaluation completion:** configure a free text/vision judge privately, resume all modalities, then review semantic correctness/faithfulness alongside diagnostics. Expand beyond clean synthetic records and include human-reviewed customer-like pages.\n6. **P2 — retrieval/observability:** expose before/after retrieval diagnostics with explicit K, instrument token/stage usage, and distinguish retrieval similarity from answer trust. Add an isolated authenticated end-to-end evaluation environment for clickable citations/queue/upload timing.',
 '## Formulas and limitations',
 'Precision@K = relevant returned chunks / K (missing slots count nonrelevant). Recall@K = unique relevant returned / all relevant chunks. Hit@K = 1 when any relevant chunk is returned. MRR@K = reciprocal rank of first relevant hit or 0. DCG = sum(binary relevance/log2(rank+1)); NDCG divides by ideal DCG at K. AP@K = sum(precision at each relevant rank)/all relevant chunks; MAP averages AP over answerable questions. Final precision uses actual returned-set size; final MAP uses all returned chunks. No duplicate chunks receive extra credit.',
 'CER = character Levenshtein distance / reference character count; WER = token Levenshtein distance / reference token count after lowercasing and whitespace normalization. OCR edit rates can exceed 100%. Text completeness = multiset reference word overlap / reference words. Cell content accuracy = cells whose exact text occurs on the matching page / annotated cells. Structured cell/row-column accuracy requires explicit app structural output; absent output yields 0. Figure recall = dedicated detected figures / annotated figures. Term coverage = matching independently authored answer tokens/terms / expected terms. It is not semantic accuracy. Source citation accuracy requires gold page/chunk and exact substring in that chunk. p95 uses nearest-rank ceil(0.95*n).',
 'Limitations: 20 clean synthetic pages; diagram/chart figures deliberately rasterized, creating a useful but nonrepresentative modality challenge; no long-page boundary test; page-level gold mapping broadens chunk relevance; no external judge credentials; no app caption or table detector output; no numeric trust scores; no authenticated clickable citation verification; core in-memory pipeline only. These omissions are never claimed as passed.',
 '## Re-run',
 'See README.md. From the app root: `python evaluation/run_eval.py`. To resume one slice: `python evaluation/run_eval.py --modality chart`. Completed question/model caches are reused; configure evaluation/.env privately to resume missing judge metrics. No model downloads occur during evaluation.',
 '## Primary references',
 '- RAGAS metrics: https://docs.ragas.io/en/v0.2.15/concepts/metrics/available_metrics/\n- RAGAS pinned implementation: https://github.com/explodinggradients/ragas/tree/v0.2.15/src/ragas/metrics\n- OpenRouter free models: https://openrouter.ai/docs/guides/routing/model-variants/free\n- App implementation: worker/ingestion.py, worker/models.py, worker/retrieval.py (read-only).']

 # Supplementary per-modality reranking, final-set and stage metrics.
 sections += ['## Supplementary modality metrics']
 for mod in ['text','table','image','chart','scanned']:
  subset=[r for r in answerable if r['modality']==mod]
  sections += ['### '+mod+' before/after reranking',table(['Stage','K','P','R','Hit','MRR','NDCG','MAP'],[[label,k]+[pct(avg([r[field][str(k)][metric] for r in subset])) for metric in ['precision','recall','hit','mrr','ndcg','ap']] for label,field in [('Before (five-result budget)','before_metrics'),('After (actual final output)','metrics')] for k in [1,3,5,10]]),table(['Final set','Precision','Recall','MAP'],[[mod]+[pct(avg([r['final_metrics'][metric] for r in subset])) for metric in ['precision','recall','ap']]])]
 sections += [table(['Modality','Call stage','Mean s','p95 s'],[[mod,stage,f'{avg(vals):.3f}',f'{sorted(vals)[mathceil(.95*len(vals))-1]:.3f}'] for mod in ['text','table','image','chart','scanned'] for stage in ['text_embedding','image_embedding','reranking','generation'] if (vals:=[c['seconds'] for r in rs if r['modality']==mod for c in r['stage_calls'] if c['stage']==stage])])]
 corpus=json.loads((E/'cache/corpus.json').read_text())['chunks']
 lookup={c['id']:c for c in corpus}
 def contains(text,terms):
  import re
  return all(re.search(r'(?<!\w)'+re.escape(str(t).lower())+r'(?!\w)',text.lower()) for t in terms)
 qs=json.loads((E/'testset.json').read_text())['questions'];chunk_rows=[]
 for mod in ['text','table','image','chart','scanned']:
  eligible=[q for q in qs if q['modality']==mod and len(q['source_pages'])==1 and not q['unanswerable']]
  available=split=0
  for q in eligible:
   chunks=[lookup[c]['text'] for c in q['reference_chunks'] if c in lookup]
   if contains(' '.join(chunks),q['evidence_terms']):
    available+=1;split+=not any(contains(c,q['evidence_terms']) for c in chunks)
  chunk_rows.append([mod,len(eligible),available,split,pct(split/available if available else None)])
 sections += ['## Single-page evidence splitting diagnostic',table(['Modality','Questions','All terms present somewhere','Terms split across chunks','Split rate among present'],chunk_rows),'This exact-term diagnostic only covers authored single-page evidence. Absent visual terms are reported as absent, not as a favorable zero split rate. Multi-page questions are intentionally excluded.']
 # Export every numeric per-question score, not just a compact subset.
 import csv
 flat=[]
 for r in rs:
  row={k:r.get(k) for k in ['id','modality','type','question','reference_answer','unanswerable','abstention','reference_term_coverage','correct_negative','negative_nonabstention','citation_source_accuracy','citation_visual_region_match','has_valid_citation','clickable_app_citation','source_modality_hit','evidence_present_in_text']}
  row.update(answer=r['result']['answer'],mode=r['result']['mode'],confidence=r['result']['confidence'],source_pages=json.dumps(r['source_pages']),retrieved_ids=json.dumps(r['retrieved_ids']),relevant_ids=json.dumps(r['relevant_ids']))
  for name in ['metrics','before_metrics']:
   for k,vals in r[name].items():
    for metric in ['precision','recall','hit','mrr','ndcg','ap']:row[f'{name}_{metric}_at_{k}']=vals.get(metric) if vals else None
  for key,val in r['ragas'].items():
   if isinstance(val,(int,float)) or val is None:row['ragas_'+key]=val
  for key,val in r['timings'].items():row['seconds_'+key]=val
  row['prompt_tokens']=sum(u.get('prompt_eval_count') or 0 for u in r['token_usage']);row['generated_tokens']=sum(u.get('eval_count') or 0 for u in r['token_usage']);flat.append(row)
 with (E/'results.csv').open('w',newline='') as f:
  fields=list(dict.fromkeys(k for row in flat for k in row));writer=csv.DictWriter(f,fieldnames=fields);writer.writeheader();writer.writerows(flat)
 (E/'RAG_EVALUATION_REPORT.md').write_text('\n\n'.join(sections)+'\n')
 print('\nSUMMARY SCORECARD\n'+table(['Component','Score/status','Interpretation'],scores),flush=True)
 print(f'Overall semantic score: UNAVAILABLE; operational diagnostic index {pct(diagnostic)}. {len(rs)}/60 questions. Report: evaluation/RAG_EVALUATION_REPORT.md',flush=True)
def mathceil(x):return __import__('math').ceil(x)
